using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectWardens {public static string Run()=>string.Join("\n",new[]{"MonsterOrc","MonsterMutant","OrkBerserker"}.Select(n=>{var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/01_Prefabs/Bosses/"+n+".prefab");var b=p.GetComponent<Codice.Bosses.BossCharacter>();return n+" native="+b.useNativeAnimator+" visual="+b.visual.name+" hands="+string.Join(",",p.GetComponentsInChildren<Transform>().Where(t=>t.name.ToLower().Contains("hand")||t.name.ToLower().Contains("weapon")).Select(t=>t.name));}));}
